static void draw_blade_rail(int active)
{
    int index;

    for (index = 0; index < 3; ++index)
    {
        int x = index * 8;
        unsigned top = index == active ? GREEN_TOP : BLADE_TOP;
        unsigned bottom = index == active ? GREEN_BOTTOM : BLADE_BOTTOM;

        fill_gradient(x, 39, 8, LCD_HEIGHT - 57, top, bottom);
        rb->lcd_set_foreground(index == active ? GREEN_DARK : SILVER_LINE);
        rb->lcd_vline(x + 7, 39, LCD_HEIGHT - 19);
    }
}

static void draw_card(int x, int y, int width, int height, bool selected)
{
    rb->lcd_set_foreground(CARD_SHADOW);
    rb->lcd_fillrect(x + 2, y + 2, width, height);
    if (selected)
        fill_gradient(x, y, width, height, GREEN_TOP, GREEN_BOTTOM);
    else
    {
        rb->lcd_set_foreground(DASH_WHITE);
        rb->lcd_fillrect(x, y, width, height);
        rb->lcd_set_foreground(CARD_LINE);
        rb->lcd_drawrect(x, y, width, height);
    }
}

static bool load_art(const char *path)
{
    int result;

    rb->memset(&art, 0, sizeof(art));
    art.data = art_data;
    result = rb->read_bmp_file(path, &art, sizeof(art_data),
                               FORMAT_NATIVE, NULL);
    return result > 0;
}

static void schedule_art(void)
{
    art_owner = -1;
    art_due = *rb->current_tick + HZ / 7;
}

static bool load_due_art(void)
{
    const char *path = "";
    int owner;

    if (!TIME_AFTER(*rb->current_tick, art_due))
        return false;
    if (screen == SCREEN_GAMES && game_count > 0)
    {
        owner = selected_game;
        path = games[selected_game].cover;
        art_is_achievement = false;
    }
    else if ((screen == SCREEN_ACHIEVEMENTS || screen == SCREEN_DETAIL) &&
             achievement_count > 0)
    {
        owner = selected_achievement;
        path = achievements[selected_achievement].unlocked ?
            achievements[selected_achievement].unlocked_badge :
            achievements[selected_achievement].locked_badge;
        art_is_achievement = true;
    }
    else
        return false;
    if (art_owner == owner &&
        art_is_achievement == (screen != SCREEN_GAMES))
        return false;
    art_owner = load_art(path) ? owner : -2;
    return true;
}

static bool load_avatar_profile(void)
{
    char path[MAX_PATH];
    char line[160];
    int fd;

    avatar_profile_checked = true;
    fd = rb->open(ACH_AVATAR_CURRENT, O_RDONLY);
    if (fd < 0 || rb->read_line(fd, avatar_generation,
                                sizeof(avatar_generation)) <= 0)
    {
        if (fd >= 0)
            rb->close(fd);
        avatar_pack_loaded = false;
        avatar_totals_from_catalog();
        return false;
    }
    rb->close(fd);
    rb->snprintf(path, sizeof(path),
                 ACH_AVATAR_ROOT "/generations/%s/profile.v1.tsv",
                 avatar_generation);
    fd = rb->open(path, O_RDONLY);
    if (fd < 0)
    {
        avatar_pack_loaded = false;
        avatar_totals_from_catalog();
        return false;
    }
    avatar_totals_from_catalog();
    rb->read_line(fd, line, sizeof(line));
    while (rb->read_line(fd, line, sizeof(line)) > 0)
    {
        char *cursor = line;
        char *key = next_field(&cursor);
        char *value = next_field(&cursor);

        if (!rb->strcmp(key, "display_name"))
            rb->strlcpy(avatar_name, value, sizeof(avatar_name));
        else if (!rb->strcmp(key, "favorite_clip"))
        {
            int index;
            for (index = 0; index < AVATAR_EMOTE_COUNT; ++index)
                if (!rb->strcmp(value, avatar_clip_ids[index]))
                    avatar_emote_clip = index;
        }
        else if (!rb->strcmp(key, "games"))
            avatar_games = rb->atoi(value);
        else if (!rb->strcmp(key, "unlocked"))
            avatar_unlocked = rb->atoi(value);
        else if (!rb->strcmp(key, "achievements"))
            avatar_total = rb->atoi(value);
        else if (!rb->strcmp(key, "gamerscore"))
            avatar_score = rb->atoi(value);
    }
    rb->close(fd);
    avatar_clip = AVATAR_TURNTABLE_CLIP;
    avatar_pack_loaded = true;
    return true;
}

static bool decode_avatar_frame(int frame)
{
    const unsigned char *cursor;
    const unsigned char *end;
    size_t pixel = 0;
    uint32_t offset;
    uint32_t length;

    if (!avatar_clip_loaded || frame < 0 || frame >= avatar_frame_count)
        return false;
    offset = avatar_offsets[frame];
    if (offset + 4 > avatar_clip_size)
        return false;
    length = read_le32(avatar_clip_data + offset);
    if (offset + 4 + length > avatar_clip_size)
        return false;
    cursor = avatar_clip_data + offset + 4;
    end = cursor + length;
    while (cursor + 2 <= end && pixel < (size_t)(avatar_width * avatar_height))
    {
        uint16_t command = read_le16(cursor);
        unsigned kind = avatar_rav2 ? command & 0xc000 :
                        command & 0x8000;
        size_t run = (command & (avatar_rav2 ? 0x3fff : 0x7fff)) + 1;
        cursor += 2;
        if (pixel + run > (size_t)(avatar_width * avatar_height))
            return false;
        if (avatar_rav2 && kind == 0xc000)
        {
            size_t index;
            fb_data value;

            if (cursor + 2 > end)
                return false;
            value = (fb_data)read_le16(cursor);
            cursor += 2;
            for (index = 0; index < run; ++index)
                avatar_pixels[pixel + index] = value;
        }
        else if (kind & 0x8000)
        {
            size_t index;
            if (cursor + run * 2 > end)
                return false;
            for (index = 0; index < run; ++index)
                avatar_pixels[pixel + index] =
                    (fb_data)read_le16(cursor + index * 2);
            cursor += run * 2;
        }
        else if (frame == 0 || avatar_keyframes)
            return false;
        pixel += run;
    }
    if (cursor != end || pixel != (size_t)(avatar_width * avatar_height))
        return false;
    avatar_frame = frame;
    return true;
}

static void schedule_avatar_clip(void)
{
    avatar_clip_pending = true;
    avatar_clip_due = *rb->current_tick + HZ / 8;
    avatar_clip_loaded = false;
}

static void rotate_avatar(int direction)
{
    int count = 24;

    if (avatar_clip == AVATAR_TURNTABLE_CLIP &&
        avatar_clip_loaded && avatar_frame_count > 0)
        count = avatar_frame_count;
    avatar_turntable_frame =
        (avatar_turntable_frame + direction + count) % count;
    avatar_paused = true;
    if (avatar_clip != AVATAR_TURNTABLE_CLIP)
    {
        avatar_clip = AVATAR_TURNTABLE_CLIP;
        schedule_avatar_clip();
    }
    else if (avatar_clip_loaded && avatar_keyframes)
        decode_avatar_frame(avatar_turntable_frame);
    else
        schedule_avatar_clip();
}

static bool load_avatar_clip(void)
{
    char path[MAX_PATH];
    int index;

    if (!avatar_pack_loaded)
        return false;
    rb->snprintf(path, sizeof(path),
        ACH_AVATAR_ROOT "/generations/%s/clips/%s.rav",
        avatar_generation, avatar_clip_ids[avatar_clip]);
    if (!read_exact_file(path, avatar_clip_data, sizeof(avatar_clip_data),
                         &avatar_clip_size))
        return false;
    if (avatar_clip_size < 20 ||
        (rb->memcmp(avatar_clip_data, "RAV1", 4) &&
         rb->memcmp(avatar_clip_data, "RAV2", 4)))
        return false;
    avatar_rav2 = !rb->memcmp(avatar_clip_data, "RAV2", 4);
    avatar_opaque = avatar_rav2 && (read_le16(avatar_clip_data + 12) & 4);
    avatar_keyframes = avatar_rav2 &&
                       (read_le16(avatar_clip_data + 12) & 8);
    avatar_width = read_le16(avatar_clip_data + 4);
    avatar_height = read_le16(avatar_clip_data + 6);
    avatar_frame_count = read_le16(avatar_clip_data + 8);
    avatar_frame_ms = read_le16(avatar_clip_data + 10);
    if (avatar_width <= 0 || avatar_width > AVATAR_WIDTH ||
        avatar_height <= 0 || avatar_height > AVATAR_HEIGHT ||
        avatar_frame_count <= 0 || avatar_frame_count > 24 ||
        avatar_frame_ms < 40 ||
        (size_t)(20 + avatar_frame_count * 4) > avatar_clip_size)
        return false;
    for (index = 0; index < avatar_frame_count; ++index)
    {
        avatar_offsets[index] = read_le32(avatar_clip_data + 20 + index * 4);
        if (avatar_offsets[index] >= avatar_clip_size)
            return false;
    }
    if (avatar_offsets[0] < (uint32_t)(20 + avatar_frame_count * 4) ||
        avatar_crc32(avatar_clip_data + avatar_offsets[0],
                     avatar_clip_size - avatar_offsets[0]) !=
        read_le32(avatar_clip_data + 16))
        return false;
    rb->memset(avatar_pixels, 0xff, sizeof(avatar_pixels));
    avatar_clip_loaded = true;
    avatar_frame_started = *rb->current_tick;
    if (!decode_avatar_frame(0))
        return false;
    if (avatar_clip == AVATAR_TURNTABLE_CLIP &&
        avatar_turntable_frame > 0 &&
        avatar_turntable_frame < avatar_frame_count)
    {
        avatar_frame_started = *rb->current_tick -
            avatar_turntable_frame * avatar_frame_ms * HZ / 1000;
        return decode_avatar_frame(avatar_turntable_frame);
    }
    return true;
}

#ifndef HAVE_HARDWARE_BEEP
static bool load_avatar_sounds(void)
{
    char path[MAX_PATH];
    unsigned int rate = rb->mixer_get_frequency();
    int index;

    if (!avatar_pack_loaded || (rate != 44100 && rate != 48000))
        return false;
    rb->snprintf(path, sizeof(path),
        ACH_AVATAR_ROOT "/generations/%s/sounds/ui-%u.uib",
        avatar_generation, rate);
    if (!read_exact_file(path, avatar_sound_data, sizeof(avatar_sound_data),
                         &avatar_sound_size) || avatar_sound_size < 48 ||
        rb->memcmp(avatar_sound_data, "UIB1", 4) ||
        read_le32(avatar_sound_data + 4) != rate ||
        read_le16(avatar_sound_data + 8) != 3)
        return false;
    for (index = 0; index < 3; ++index)
    {
        size_t entry = 12 + index * 12;
        avatar_sound_offsets[index] = read_le32(avatar_sound_data + entry + 4);
        avatar_sound_lengths[index] = read_le32(avatar_sound_data + entry + 8);
        if (avatar_sound_offsets[index] + avatar_sound_lengths[index] >
            avatar_sound_size)
            return false;
    }
    avatar_sound_loaded = true;
    rb->mixer_channel_set_amplitude(PCM_MIXER_CHAN_BEEP, MIX_AMP_UNITY);
    return true;
}

static void play_avatar_sound(int sound)
{
    if (avatar_sound_mode != 2 || !avatar_sound_loaded ||
        sound < 0 || sound > 2)
        return;
    if (!avatar_sounds_over_music && (rb->audio_status() & AUDIO_STATUS_PLAY))
        return;
    rb->mixer_channel_stop(PCM_MIXER_CHAN_BEEP);
    rb->mixer_channel_play_data(
        PCM_MIXER_CHAN_BEEP, NULL,
        avatar_sound_data + avatar_sound_offsets[sound],
        avatar_sound_lengths[sound]);
}
#else
static void play_avatar_sound(int sound)
{
    (void)sound;
}
#endif

static bool load_due_avatar_assets(void)
{
    bool changed = false;

    if (!avatar_profile_checked)
    {
        changed = load_avatar_profile();
        load_avatar_preferences();
#ifndef HAVE_HARDWARE_BEEP
        load_avatar_sounds();
#endif
    }
    if (avatar_clip_pending &&
        TIME_AFTER(*rb->current_tick, avatar_clip_due) &&
        rb->button_queue_count() == 0)
    {
        avatar_clip_pending = false;
        changed = load_avatar_clip() || changed;
    }
    return changed;
}

static bool advance_avatar_frame(void)
{
    long elapsed;
    int target;

    if (screen != SCREEN_AVATAR || !avatar_clip_loaded || avatar_paused ||
        avatar_motion == 0 || avatar_frame_count < 2)
        return false;
    elapsed = *rb->current_tick - avatar_frame_started;
    target = (int)((elapsed * 1000 / HZ) / avatar_frame_ms);
    if (avatar_motion == 1)
        target /= 2;
    if (avatar_clip == AVATAR_TURNTABLE_CLIP || avatar_idle_emotes)
        target %= avatar_frame_count;
    else if (target >= avatar_frame_count)
        target = avatar_frame_count - 1;
    if (target == avatar_frame)
        return false;
    if (avatar_keyframes)
        return decode_avatar_frame(target % avatar_frame_count);
    if (target < avatar_frame)
    {
        if (!decode_avatar_frame(0))
            return false;
    }
    while (avatar_frame < target)
        if (!decode_avatar_frame(avatar_frame + 1))
            return false;
    return true;
}

static bool avatar_transition_active(void)
{
    if (screen != SCREEN_AVATAR || avatar_motion == 0)
        return false;
    return !TIME_AFTER(*rb->current_tick,
                       avatar_enter_started + MAX(1, HZ / 5));
}

static bool load_catalog(void)
{
    char generation[40];
    char path[MAX_PATH];
    char line[1024];
    int fd;

    fd = rb->open(ACH_CURRENT, O_RDONLY);
    if (fd < 0 || rb->read_line(fd, generation, sizeof(generation)) <= 0)
    {
        if (fd >= 0)
            rb->close(fd);
        return false;
    }
    rb->close(fd);
    rb->snprintf(path, sizeof(path), ACH_ROOT "/generations/%s/catalog.tsv",
                 generation);
    fd = rb->open(path, O_RDONLY);
    if (fd < 0)
        return false;
    game_count = 0;
    rb->read_line(fd, line, sizeof(line));
    while (game_count < MAX_GAMES &&
           rb->read_line(fd, line, sizeof(line)) > 0)
    {
        struct achievement_game *game = &games[game_count];
        char *cursor = line;

        rb->memset(game, 0, sizeof(*game));
        copy_field(game->key, sizeof(game->key), &cursor);
        copy_field(game->title, sizeof(game->title), &cursor);
        copy_field(game->console, sizeof(game->console), &cursor);
        copy_field(game->kind, sizeof(game->kind), &cursor);
        copy_field(game->cover, sizeof(game->cover), &cursor);
        copy_field(game->achievements, sizeof(game->achievements), &cursor);
        game->unlocked = int_field(&cursor);
        game->total = int_field(&cursor);
        game->earned_points = int_field(&cursor);
        game->total_points = int_field(&cursor);
        next_field(&cursor);
        copy_field(game->launch_target, sizeof(game->launch_target), &cursor);
        if (game->key[0] && game->title[0] && game->achievements[0])
            ++game_count;
    }
    rb->close(fd);
    return game_count > 0;
}

static const char *console_filter_name(int filter)
{
    if (filter <= 0 || filter > console_count)
        return "All Games";
    return consoles[filter - 1];
}

static void collect_consoles(void)
{
    int game_index;

    console_count = 0;
    for (game_index = 0; game_index < game_count; ++game_index)
    {
        int console_index;
        bool known = false;

        for (console_index = 0; console_index < console_count;
             ++console_index)
        {
            if (!rb->strcasecmp(consoles[console_index],
                                games[game_index].console))
            {
                known = true;
                break;
            }
        }
        if (!known && console_count < MAX_CONSOLES)
            rb->strlcpy(consoles[console_count++],
                        games[game_index].console,
                        sizeof(consoles[0]));
    }
}

static void rebuild_visible_games(void)
{
    int previous_game = selected_game;
    int game_index;

    visible_game_count = 0;
    selected_game_row = 0;
    for (game_index = 0; game_index < game_count; ++game_index)
    {
        if (console_filter > 0 &&
            rb->strcasecmp(games[game_index].console,
                           console_filter_name(console_filter)))
            continue;
        visible_games[visible_game_count] = game_index;
        if (game_index == previous_game)
            selected_game_row = visible_game_count;
        ++visible_game_count;
    }
    if (visible_game_count > 0)
        selected_game = visible_games[selected_game_row];
}

static void wait_for_select_release(void)
{
    while (rb->button_status() & BUTTON_SELECT)
        rb->sleep(1);
    rb->button_clear_queue();
}

static void load_sessions(void)
{
    char line[512];
    int fd = rb->open(ACH_SESSIONS, O_RDONLY);

    if (fd < 0)
        return;
    rb->read_line(fd, line, sizeof(line));
    while (rb->read_line(fd, line, sizeof(line)) > 0)
    {
        char target[MAX_PATH];
        char *cursor = line;
        int sessions;
        long seconds;
        int index;

        copy_field(target, sizeof(target), &cursor);
        sessions = int_field(&cursor);
        seconds = rb->strtol(next_field(&cursor), NULL, 10);
        for (index = 0; index < game_count; ++index)
        {
            struct achievement_game *game = &games[index];
            if (rb->strcasecmp(target, game->launch_target))
                continue;
            game->sessions = sessions;
            game->seconds = seconds;
            if (!rb->strcmp(game->kind, "local-baseline"))
            {
                game->unlocked = (sessions >= 1) + (seconds >= 15 * 60) +
                    (seconds >= 60 * 60) + (sessions >= 10);
                game->earned_points = (sessions >= 1 ? 5 : 0) +
                    (seconds >= 15 * 60 ? 10 : 0) +
                    (seconds >= 60 * 60 ? 20 : 0) +
                    (sessions >= 10 ? 15 : 0);
            }
            break;
        }
    }
    rb->close(fd);
}

static bool imported_unlock_info(const struct achievement_game *game,
                                 const char *id, bool *imported,
                                 int *points)
{
    char line[4096];
    int fd = rb->open(game->achievements, O_RDONLY);

    if (fd < 0)
        return false;
    rb->read_line(fd, line, sizeof(line));
    while (rb->read_line(fd, line, sizeof(line)) > 0)
    {
        char row_id[32];
        char state[16];
        char *cursor = line;

        copy_field(row_id, sizeof(row_id), &cursor);
        if (rb->strcmp(row_id, id))
            continue;
        next_field(&cursor);
        next_field(&cursor);
        *points = int_field(&cursor);
        next_field(&cursor);
        next_field(&cursor);
        copy_field(state, sizeof(state), &cursor);
        *imported = !rb->strcmp(state, "unlocked");
        rb->close(fd);
        return true;
    }
    rb->close(fd);
    return false;
}

static void load_device_unlock_totals(void)
{
    char line[256];
    int fd = rb->open(ACH_UNLOCKS, O_RDONLY);

    if (fd < 0)
        return;
    rb->read_line(fd, line, sizeof(line));
    while (rb->read_line(fd, line, sizeof(line)) > 0)
    {
        char key[24];
        char id[32];
        char *cursor = line;
        int index;

        copy_field(key, sizeof(key), &cursor);
        copy_field(id, sizeof(id), &cursor);
        for (index = 0; index < game_count; ++index)
        {
            bool imported = false;
            int points = 0;

            if (rb->strcmp(key, games[index].key) ||
                !rb->strcmp(games[index].kind, "local-baseline"))
                continue;
            if (imported_unlock_info(&games[index], id, &imported, &points) &&
                !imported)
            {
                games[index].unlocked++;
                games[index].earned_points += points;
            }
            break;
        }
    }
    rb->close(fd);
}

static bool baseline_unlocked(const struct achievement_game *game,
                              const char *id)
{
    if (rb->strcmp(game->kind, "local-baseline"))
        return false;
    if (!rb->strcmp(id, "local-first-play"))
        return game->sessions >= 1;
    if (!rb->strcmp(id, "local-15-minutes"))
        return game->seconds >= 15 * 60;
    if (!rb->strcmp(id, "local-60-minutes"))
        return game->seconds >= 60 * 60;
    if (!rb->strcmp(id, "local-10-sessions"))
        return game->sessions >= 10;
    return false;
}

static void load_known_unlocks(void)
{
    char line[256];
    int fd = rb->open(ACH_UNLOCKS, O_RDONLY);

    known_unlock_count = 0;
    if (fd < 0)
        return;
    rb->read_line(fd, line, sizeof(line));
    while (known_unlock_count < MAX_ACHIEVEMENTS &&
           rb->read_line(fd, line, sizeof(line)) > 0)
    {
        char key[24];
        char source[32];
        char *cursor = line;

        copy_field(key, sizeof(key), &cursor);
        if (rb->strcmp(key, games[selected_game].key))
            continue;
        copy_field(known_unlocks[known_unlock_count],
                   sizeof(known_unlocks[known_unlock_count]), &cursor);
        next_field(&cursor);
        copy_field(source, sizeof(source), &cursor);
        known_unlock_hardcore[known_unlock_count] =
            !rb->strcmp(source, "ipod-hardcore");
        if (known_unlocks[known_unlock_count][0])
            ++known_unlock_count;
    }
    rb->close(fd);
}

static bool unlock_is_known(const char *id)
{
    int index;

    for (index = 0; index < known_unlock_count; ++index)
        if (!rb->strcmp(known_unlocks[index], id))
            return true;
    return false;
}

static bool unlock_is_ipod_hardcore(const char *id)
{
    int index;

    for (index = 0; index < known_unlock_count; ++index)
        if (!rb->strcmp(known_unlocks[index], id))
            return known_unlock_hardcore[index];
    return false;
}

static unsigned long next_event_sequence(void)
{
    char line[256];
    unsigned long sequence = 0;
    int fd = rb->open(ACH_EVENTS, O_RDONLY);

    if (fd < 0)
        return 1;
    rb->read_line(fd, line, sizeof(line));
    while (rb->read_line(fd, line, sizeof(line)) > 0)
    {
        unsigned long value = rb->strtoul(line, NULL, 10);
        if (value > sequence)
            sequence = value;
    }
    rb->close(fd);
    return sequence + 1;
}

static uint32_t achievement_notification_id(const char *game_key,
                                            const char *achievement_id)
{
    uint32_t hash = 2166136261u;
    const unsigned char *text;

    for (text = (const unsigned char *)game_key; *text; ++text)
    {
        hash ^= *text;
        hash *= 16777619u;
    }
    hash ^= ':';
    hash *= 16777619u;
    for (text = (const unsigned char *)achievement_id; *text; ++text)
    {
        hash ^= *text;
        hash *= 16777619u;
    }
    return hash ? hash : 1;
}

static void record_unlock_event(const struct achievement_item *item)
{
    long timestamp;
    unsigned long sequence;
    bool unlock_written = false;
    bool event_written = false;
    int fd;

    if (unlock_is_known(item->id) ||
        known_unlock_count >= MAX_ACHIEVEMENTS)
        return;
    timestamp = (long)rb->mktime(rb->get_time());
    sequence = next_event_sequence();
    fd = rb->open(ACH_UNLOCKS, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (fd >= 0)
    {
        if (rb->lseek(fd, 0, SEEK_END) == 0)
            rb->fdprintf(fd,
                         "game_key\tachievement_id\tunlock_time\tsource\n");
        unlock_written = rb->fdprintf(fd, "%s\t%s\t%ld\trockpod-local\n",
                     games[selected_game].key, item->id, timestamp) > 0;
        rb->close(fd);
    }
    fd = rb->open(ACH_EVENTS, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (fd >= 0)
    {
        if (rb->lseek(fd, 0, SEEK_END) == 0)
            rb->fdprintf(fd,
                         "sequence\tgame_key\tachievement_id\tevent_time\tmode\tclient\n");
        event_written = rb->fdprintf(fd,
                     "%lu\t%s\t%s\t%ld\tlocal\tipod\n", sequence,
                     games[selected_game].key, item->id, timestamp) > 0;
        rb->close(fd);
    }
    if (!unlock_written || !event_written)
        return;
    rb->strlcpy(known_unlocks[known_unlock_count++], item->id,
                sizeof(known_unlocks[0]));
    known_unlock_hardcore[known_unlock_count - 1] = false;
#ifdef HAVE_IPODJS_UI
    {
        struct notification_request request;

        rb->memset(&request, 0, sizeof(request));
        request.source = NOTIFICATION_SOURCE_ACHIEVEMENTS;
        request.kind = NOTIFICATION_ACHIEVEMENT_UNLOCKED;
        request.stable_id = achievement_notification_id(
            games[selected_game].key, item->id);
        request.timestamp = timestamp;
        rb->strlcpy(request.title, "Achievement Unlocked",
                    sizeof(request.title));
        rb->snprintf(request.body, sizeof(request.body), "%s — %s",
                     games[selected_game].title, item->title);
        rb->strlcpy(request.route, "achievements",
                    sizeof(request.route));
        rb->notification_post(&request);
    }
#endif
}

static bool load_achievements(void)
{
    char line[4096];
    int fd;
    int total_unlocked = 0;
    int earned_points = 0;

    achievement_count = 0;
    selected_achievement = 0;
    if (selected_game < 0 || selected_game >= game_count)
        return false;
    fd = rb->open(games[selected_game].achievements, O_RDONLY);
    if (fd < 0)
        return false;
    load_known_unlocks();
    rb->read_line(fd, line, sizeof(line));
    while (achievement_count < MAX_ACHIEVEMENTS &&
           rb->read_line(fd, line, sizeof(line)) > 0)
    {
        struct achievement_item *item = &achievements[achievement_count];
        char state[16];
        char *cursor = line;

        rb->memset(item, 0, sizeof(*item));
        copy_field(item->id, sizeof(item->id), &cursor);
        copy_field(item->title, sizeof(item->title), &cursor);
        copy_field(item->description, sizeof(item->description), &cursor);
        item->points = int_field(&cursor);
        copy_field(item->unlocked_badge, sizeof(item->unlocked_badge), &cursor);
        copy_field(item->locked_badge, sizeof(item->locked_badge), &cursor);
        copy_field(state, sizeof(state), &cursor);
        item->imported = !rb->strcmp(state, "unlocked");
        item->ipod_hardcore = unlock_is_ipod_hardcore(item->id);
        item->unlocked = item->imported || item->ipod_hardcore ||
            unlock_is_known(item->id) ||
            baseline_unlocked(&games[selected_game], item->id);
        if (item->unlocked)
        {
            ++total_unlocked;
            earned_points += item->points;
        }
        if (item->unlocked &&
            !rb->strcmp(games[selected_game].kind, "local-baseline"))
            record_unlock_event(item);
        if (!locked_only || !item->unlocked)
            ++achievement_count;
    }
    rb->close(fd);
    games[selected_game].unlocked = total_unlocked;
    games[selected_game].earned_points = earned_points;
    return achievement_count > 0;
}

