static void draw_progress(int x, int y, int width, int value, int total)
{
    int filled = total > 0 ? width * value / total : 0;

    rb->lcd_set_foreground(SILVER_LINE);
    rb->lcd_drawrect(x, y, width, 7);
    rb->lcd_set_foreground(GREEN_BOTTOM);
    if (filled > 2)
        rb->lcd_fillrect(x + 1, y + 1, filled - 2, 5);
}

