static int games_for_console(int filter)
{
    int count = 0;
    int index;

    if (filter == 0)
        return game_count;
    for (index = 0; index < game_count; ++index)
        if (!rb->strcasecmp(games[index].console,
                            console_filter_name(filter)))
            ++count;
    return count;
}

